import os
import math
import heapq
from typing import Dict, List

import networkx as nx
import pandas as pd


def _edge_cost(data):
    value = data.get("cost")
    try:
        value = float(value)
        return value if math.isfinite(value) and value >= 0 else None
    except (TypeError, ValueError):
        return None


def _edge_union_cost(G, edges):
    return sum(_edge_cost(G[u][v]) or 0.0 for u, v in edges if G.has_edge(u, v))


def _paths_to_edges(paths):
    edges = set()
    for path in paths.values():
        edges.update(zip(path, path[1:]))
    return edges


def _reachable(h, src, terminals, edges):
    sub = h.edge_subgraph(edges)
    return all(t in sub and nx.has_path(sub, src, t) for t in terminals)


def _directed_steiner_edges(h, src, terminals, max_terminals=9):
    """Exact directed Steiner dynamic program for modest terminal sets."""
    terminals = list(dict.fromkeys(t for t in terminals if t != src))
    k = len(terminals)
    if not k:
        return set()
    if k > max_terminals:
        return None

    incoming = {v: [] for v in h.nodes()}
    for u, v, data in h.edges(data=True):
        c = _edge_cost(data)
        if c is not None:
            incoming[v].append((u, c))

    count = 1 << k
    dp = [dict() for _ in range(count)]
    trace = [dict() for _ in range(count)]

    for mask in range(1, count):
        initial = {}
        actions = {}
        if mask & (mask - 1) == 0:
            terminal = terminals[mask.bit_length() - 1]
            initial[terminal] = 0.0
            actions[terminal] = ("terminal",)
        else:
            sub = (mask - 1) & mask
            while sub:
                other = mask ^ sub
                if other and sub < other:
                    for v in set(dp[sub]).intersection(dp[other]):
                        value = dp[sub][v] + dp[other][v]
                        if value < initial.get(v, float("inf")):
                            initial[v] = value
                            actions[v] = ("merge", sub)
                sub = (sub - 1) & mask

        dist = dict(initial)
        action = dict(actions)
        heap = [(cost, v) for v, cost in dist.items()]
        heapq.heapify(heap)
        while heap:
            value, v = heapq.heappop(heap)
            if value != dist.get(v):
                continue
            for u, c in incoming.get(v, ()):
                candidate = value + c
                if candidate < dist.get(u, float("inf")):
                    dist[u] = candidate
                    action[u] = ("edge", v)
                    heapq.heappush(heap, (candidate, u))
        dp[mask] = dist
        trace[mask] = action

    full = count - 1
    if src not in dp[full]:
        return None

    edges = set()
    active = set()

    def recover(mask, v):
        state = (mask, v)
        if state in active:
            return
        active.add(state)
        item = trace[mask].get(v)
        if item is None:
            active.remove(state)
            return
        if item[0] == "edge":
            w = item[1]
            edges.add((v, w))
            recover(mask, w)
        elif item[0] == "merge":
            left = item[1]
            recover(left, v)
            recover(mask ^ left, v)
        active.remove(state)

    recover(full, src)
    return edges


def _greedy_tree(h, src, terminals):
    """Several deterministic attachment orders for terminal sets too large for DP."""
    terminals = list(dict.fromkeys(t for t in terminals if t != src))
    if not terminals:
        return set()

    try:
        distance = nx.single_source_dijkstra_path_length(h, src, weight="cost")
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        distance = {}

    by_near = sorted(terminals, key=lambda t: (distance.get(t, float("inf")), str(t)))
    orders = [
        by_near,
        list(reversed(by_near)),
        sorted(terminals, key=lambda t: str(t)),
    ]
    best, best_cost = None, float("inf")

    for order in orders:
        used = set()
        feasible = True
        for dst in order:
            def marginal(u, v, data):
                if (u, v) in used:
                    return 0.0
                c = _edge_cost(data)
                return c if c is not None else float("inf")

            try:
                path = nx.dijkstra_path(h, src, dst, weight=marginal)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                feasible = False
                break
            used.update(zip(path, path[1:]))
        if feasible:
            value = _edge_union_cost(h, used)
            if value < best_cost:
                best, best_cost = used, value
    return best


def _decomposed_steiner_edges(h, src, terminals):
    """Exact local connector construction over the rooted block-cut structure."""
    terminals = list(dict.fromkeys(t for t in terminals if t != src))
    if not terminals:
        return set()

    support = h.to_undirected()
    if src not in support:
        return None
    blocks = [set(b) for b in nx.biconnected_components(support)]
    if not blocks:
        return None

    membership = {}
    for i, block in enumerate(blocks):
        for v in block:
            membership.setdefault(v, []).append(i)
    roots = membership.get(src, [])
    if not roots:
        return None

    articulation = set(nx.articulation_points(support))
    root = roots[0]
    parent = {root: None}
    entry = {root: src}
    depth = {root: 0}
    queue = [root]
    order = []

    while queue:
        block_id = queue.pop(0)
        order.append(block_id)
        for a in blocks[block_id].intersection(articulation):
            for child in membership.get(a, []):
                if child not in parent:
                    parent[child] = block_id
                    entry[child] = a
                    depth[child] = depth[block_id] + 1
                    queue.append(child)

    owner = {}
    for t in terminals:
        choices = [b for b in membership.get(t, []) if b in parent]
        if not choices:
            return None
        owner[t] = max(choices, key=lambda b: depth[b])

    selected = set()
    for b in order:
        local_terminals = {t for t in terminals if owner[t] == b}
        for child, p in parent.items():
            if p == b:
                local_terminals.add(entry[child])
        if not local_terminals:
            continue
        local = h.subgraph(blocks[b]).copy()
        local_edges = _directed_steiner_edges(local, entry[b], local_terminals)
        if local_edges is None:
            local_edges = _greedy_tree(local, entry[b], local_terminals)
        if local_edges is None:
            return None
        selected.update(local_edges)

    return selected if _reachable(h, src, terminals, selected) else None


def search_algorithm(src, dsts, G, num_partitions):
    h = G.copy()
    if src in h:
        h.remove_edges_from(list(h.in_edges(src)))
    h.remove_edges_from(list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if _edge_cost(data) is None
    ])

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(d for d in dsts if d != src))

    baseline_paths = {}
    for dst in terminals:
        try:
            baseline_paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            baseline_paths[dst] = []
    baseline_edges = _paths_to_edges(baseline_paths)

    selected = baseline_edges
    exact = _directed_steiner_edges(h, src, terminals, max_terminals=9)
    if exact is not None and _reachable(h, src, terminals, exact):
        if _edge_union_cost(h, exact) <= _edge_union_cost(h, selected):
            selected = exact
    elif terminals:
        decomposed = _decomposed_steiner_edges(h, src, terminals)
        if decomposed is not None and _reachable(h, src, terminals, decomposed):
            if _edge_union_cost(h, decomposed) <= _edge_union_cost(h, selected):
                selected = decomposed
        else:
            greedy = _greedy_tree(h, src, terminals)
            if greedy is not None and _reachable(h, src, terminals, greedy):
                if _edge_union_cost(h, greedy) <= _edge_union_cost(h, selected):
                    selected = greedy

    selected_graph = nx.DiGraph()
    selected_graph.add_nodes_from(h.nodes())
    for u, v in selected:
        if G.has_edge(u, v):
            selected_graph.add_edge(u, v, **G[u][v])

    final_paths = {src: [src]}
    for dst in terminals:
        try:
            final_paths[dst] = nx.dijkstra_path(selected_graph, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            final_paths[dst] = baseline_paths.get(dst, [])

    for dst in dsts:
        path = final_paths.get(dst, [])
        edges = [[u, v, G[u][v]] for u, v in zip(path, path[1:]) if G.has_edge(u, v)]
        for partition in range(num_partitions):
            topology.set_dst_partition_paths(dst, partition, list(edges))
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4,
                 paths: Dict[str, SingleDstPath] = None):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        self.paths[dst][str(partition)] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        key = str(partition)
        if self.paths[dst][key] is None:
            self.paths[dst][key] = []
        self.paths[dst][key].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))
    cost = pd.read_csv(cost_path or os.path.join(current_dir, "profiles/cost.csv"))
    throughput = pd.read_csv(
        throughput_path or os.path.join(current_dir, "profiles/throughput.csv")
    )

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] != row["dst_region"]:
            G.add_edge(
                row["src_region"], row["dst_region"], cost=None,
                throughput=num_vms * row["throughput_sent"] / 1e9,
            )
    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    missing = [(u, v) for u, v, d in G.edges(data=True) if d["cost"] is None]
    print("Unable to get costs for: ", missing)
    return G

